@accept_api_key_or_auth(
    api,
    method="POST",
    path="/link/exchange",
    cors_origins=FRONTEND_URL,
    json_input=ExchangeInputSchema(),
    output=exchange_response_schema(),
    tags=["Auth"],
)
def exchange(json_data, **kwargs):
    """
    Exchange Auth Code

    Exchanges a temporary authorization code for a permanent access token.
    See the [Getting Started guide](/how-to-guides/getting-started) for more details.
    """
    org_id = request.environ["org_id"]
    return exchange_helper(org_id, json_data)


@api.post("/link/exchange/<magic_link_id>")
@cross_origin(origins=LINK_URL)
@api.input(ExchangeInputSchema(), location="json")
@api.output(exchange_response_schema())
@api.doc(hide=True)
def exchange_magic_link(json_data, magic_link_id, **kwargs):
    try:
        row = get_magic_link_row(magic_link_id)
        org_id = row["org_id"]
    except:
        raise PokedexException("Magic link not found", 404, origin="trackstar")
    to_return = exchange_helper(org_id, json_data)
    connection_value = to_return["customer_id"] or to_return["connection_id"]
    NotificationService.send_notification(
        org_id,
        NotificationType.MAGIC_LINK_INSTALLED,
        {
            "connection_value": connection_value,
            "integration_name": to_return["integration_name"],
            "connection_id": to_return["connection_id"],
        },
    )
    return to_return


def exchange_helper(org_id, json_data):
    customer_id = json_data.get("customer_id")
    auth_code = json_data["auth_code"]
    try:
        auth_code_row = get_auth_code_row(auth_code)
        assert not auth_code_row["exchanged"]
    except Exception:
        raise PokedexException("Invalid auth code", 400, origin="trackstar")
    integration_name, app_integration_secret = (
        auth_code_row["integration_name"],
        auth_code_row["integration_secret"],
    )
    logger.updateConfig({"integration_name": integration_name})
    connection_additional_fields = auth_code_row["additional_fields"]
    org_private_key = get_org_private_key(org_id)

    raw_integration_secret = app_decrypt(app_integration_secret)
    org_integration_secret = org_encrypt(raw_integration_secret, org_private_key)
    integration_type = auth_code_row["integration_type"]
    integration_file = get_integration_file(integration_name, integration_type)
    link_token = auth_code_row["link_token"]
    link_token_row = get_link_token_row(link_token)
    if not customer_id:
        customer_id = link_token_row.get("customer_id")
    existing_connection_id = link_token_row["connection_id"]
    existing_crawl_frequencies = {}
    existing_disabled_functions = None
    existing_enabled_functions = None
    # a magic link can carry endpoints to disable or force-enable on the connection it
    # installs; only present when the link was created with them
    link_disabled_functions = link_token_row.get("disabled_functions")
    link_enabled_functions = link_token_row.get("enabled_functions")
    if existing_connection_id:
        try:
            resp = get_connections_row(existing_connection_id)
        except Exception:
            raise PokedexException("Connection not found", 404, origin="trackstar")
        if resp["org_id"] != org_id:
            raise PokedexException("Connection not found", 404, origin="trackstar")
        if resp["integration_name"] != integration_name:
            raise PokedexException(
                "Provided connection ID is for a different integration",
                400,
                origin="trackstar",
            )
        connection_id = existing_connection_id
        customer_id = resp["customer_id"]
        existing_crawl_frequencies = resp.get(
            "crawl_frequencies", {}
        )  # Support sandbox
        # only carry over an explicit prior selection; absence must stay absent so the
        # resolver keeps deferring to org policy
        if "disabled_functions" in resp:
            existing_disabled_functions = resp["disabled_functions"]
        if "enabled_functions" in resp:
            existing_enabled_functions = resp["enabled_functions"]
        created_at = resp.get("created_at") or dt_to_str(now())
    else:
        connection_id = uuid.uuid4().hex
        created_at = dt_to_str(now())
        # check it now that we know which integration is actually being installed. a link can
        # allow several integrations, so we can't check the disabled list until one is picked.
        if link_disabled_functions:
            validate_disabled_functions(
                integration_type, integration_name, link_disabled_functions
            )
    integration = integration_file.Integration(
        connection_id=connection_id,
        org_id=org_id,
        customer_id=customer_id,
        integration_secret=raw_integration_secret,
        connection_additional_fields=connection_additional_fields,
    )
    org_row = get_org_row(org_id)
    if integration_name == "sandbox":
        connection_id = generate_sandbox_connection_id(
            org_private_key, integration_type
        )
        # re-generate integration since sandbox connection_id is static
        integration = integration_file.Integration(
            connection_id=connection_id,
            org_id=org_id,
            customer_id=customer_id,
            integration_secret=raw_integration_secret,
            connection_additional_fields=connection_additional_fields,
        )
        integration.generate_sandbox()
    elif not existing_connection_id:
        if org_row.get("prevent_duplicate_installs"):
            integration, created_at = deduplicate_from_exchange(
                integration, created_at, integration_file, org_private_key
            )
            connection_id = integration.connection_id
    dict_to_hash = {
        "connection_id": connection_id,
        "integration_name": integration_name,
    }
    access_token = encode_access_token(dict_to_hash, org_private_key)
    access_token = f"trackstar_{access_token}"
    row_to_create = {
        "id": connection_id,
        "org_id": org_id,
        "integration_name": integration_name,
        "integration_secret": org_integration_secret,
        "additional_fields": connection_additional_fields,
        "created_at": created_at,
        "crawl_frequencies": existing_crawl_frequencies,
        "historical_sync_completed": {},
        "integration_type": integration_type,
        "customer_id": customer_id,
    }
    # on re-auth, keep whatever the existing connection already had. if it had nothing set,
    # leave it unset so it keeps following the org's setting.
    if existing_disabled_functions is not None:
        row_to_create["disabled_functions"] = existing_disabled_functions
    # on a brand-new install, save the link's disabled list onto the new connection. re-auth
    # doesn't reach this branch because it already kept the existing value above.
    elif not existing_connection_id and link_disabled_functions:
        row_to_create["disabled_functions"] = link_disabled_functions
    # same handling for enabled_functions: keep the existing connection's on re-auth,
    # otherwise save the link's on a new install
    if existing_enabled_functions is not None:
        row_to_create["enabled_functions"] = existing_enabled_functions
    elif not existing_connection_id and link_enabled_functions:
        row_to_create["enabled_functions"] = link_enabled_functions
    create_connections_row(row_to_create)
    # a brand-new connection is "created"; reconnecting an existing one is a reinstall
    event_type = (
        "connection_created" if not existing_connection_id else "connection_reinstalled"
    )
    record_event(
        org_id,

